// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { ADDED_LINES, CAPTIONS, CHANGED, DIFF_STATS, ORIGINAL, REMOVED_LINES } from './script'

function Pane({ lines, side }: { lines: string[]; side: 'left' | 'right' }) {
  const changed = side === 'left' ? REMOVED_LINES : ADDED_LINES
  return (
    <div
      data-d={`pane-${side}`}
      className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 py-2 font-mono text-[11px]"
    >
      {lines.map((line, index) => {
        const hit = changed.includes(line)
        return (
          <p
            key={line}
            data-d={`line-${side} ${hit ? `hit hit-${side}` : 'same'}`}
            className="relative flex h-[24px] items-center pl-7 pr-2 text-ink-soft"
          >
            {hit ? (
              <span
                data-d="hl"
                className="absolute inset-0 origin-left scale-x-0"
                style={{
                  background: side === 'left' ? 'rgba(251,113,133,0.16)' : 'rgba(52,211,153,0.16)',
                }}
              />
            ) : null}
            <span className="absolute left-2 w-3 text-center text-muted/60">{index + 1}</span>
            {hit ? (
              <span
                data-d="mark"
                className={`absolute left-2 w-3 text-center font-semibold opacity-0 ${side === 'left' ? 'text-rose' : 'text-emerald'}`}
              >
                {side === 'left' ? '−' : '+'}
              </span>
            ) : null}
            <span className="relative">{line}</span>
          </p>
        )
      })}
    </div>
  )
}

const build: Build = ({ tl, qa, step, final, move, click, count, wait, cursorOut }) => {
  step(0)
  tl.fromTo(
    qa('line-left'),
    { opacity: 0, x: -10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.06 },
    0.3,
  )

  step(1, '+=0.3')
  tl.fromTo(
    qa('line-right'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.06 },
  )

  step(2, '+=0.3')
  move('compare')
  click('compare')
  tl.fromTo(
    qa('scan'),
    { yPercent: -100, opacity: 1 },
    { yPercent: 700, opacity: 0.2, duration: 0.9, ease: 'power2.inOut' },
    '<',
  )
  tl.to(qa('same'), { opacity: 0.45, duration: 0.4 }, '<0.3')
  tl.to(qa('hl'), { scaleX: 1, duration: 0.45, stagger: 0.08, ease: 'expo.out' }, '<0.1')
  tl.fromTo(
    qa('mark'),
    { scale: 0, opacity: 0 },
    { scale: 1, opacity: 1, duration: 0.3, stagger: 0.08, ease: 'back.out(3)' },
    '<',
  )
  cursorOut('<0.4')

  step(3, '+=0.5')
  tl.fromTo(
    qa('chip'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.35, stagger: 0.1, ease: 'back.out(2)' },
  )
  count('added', DIFF_STATS.added, { at: '<', duration: 0.5, prefix: '+' })
  count('removed', DIFF_STATS.removed, { at: '<0.1', duration: 0.5, prefix: '−' })
  tl.fromTo(qa('tick'), { scaleX: 0 }, { scaleX: 1, duration: 0.3, stagger: 0.06 }, '<')
  final('+=0.3')
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Text Diff comparing two config files and highlighting added and removed lines"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="compare"
            className="rounded-lg bg-[var(--accent)] px-3 py-1.5 text-[10.5px] font-medium text-canvas"
          >
            Compare
          </span>
        }
      >
        <div className="flex h-full flex-col gap-2">
          <div className="grid grid-cols-2 gap-2">
            <Label>Input A</Label>
            <Label>Input B</Label>
          </div>
          <div className="relative flex min-h-0 flex-1 gap-2">
            <Pane lines={ORIGINAL} side="left" />
            <Pane lines={CHANGED} side="right" />
            <span
              data-d="scan"
              className="pointer-events-none absolute inset-x-0 top-0 h-6 opacity-0"
              style={{
                background:
                  'linear-gradient(180deg, transparent, rgba(129,140,248,0.35), transparent)',
              }}
            />
          </div>
          <div className="flex items-center gap-2 text-[10.5px]">
            <span
              data-d="chip"
              className="rounded-full bg-emerald/15 px-2.5 py-1 font-mono text-emerald opacity-0"
            >
              <span data-d="added">+0</span> added
            </span>
            <span
              data-d="chip"
              className="rounded-full bg-rose/15 px-2.5 py-1 font-mono text-rose opacity-0"
            >
              <span data-d="removed">−0</span> removed
            </span>
            <span className="ml-auto flex h-4 w-24 items-center gap-1">
              {Array.from({ length: DIFF_STATS.removed + DIFF_STATS.added }, (_, index) => (
                <span
                  key={index}
                  data-d="tick"
                  className={`h-full flex-1 origin-left scale-x-0 rounded-sm ${index < DIFF_STATS.removed ? 'bg-rose/60' : 'bg-emerald/60'}`}
                />
              ))}
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
